WITH with_windows AS (SELECT *, RANK() OVER (PARTITION BY dept_name, location ORDER BY budget DESC NULLS LAST) AS budget_rank, AVG(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS budget_avg_2 FROM departments) SELECT CASE WHEN budget_avg_2 >= 3864974 THEN 'LARGE' ELSE 'SMALL' END AS budget_avg_2_tier, ROUND(SUM(budget) / NULLIF(COUNT(CASE WHEN dept_name = 'Sales' THEN 1 END), 0), 2) AS budget_per_sales, COUNT(CASE WHEN location = 'London' THEN 1 END) AS london_count, SUM(budget) AS total_budget, APPROX_PERCENTILE(budget_rank, ARRAY(0.25, 0.5, 0.75)) AS budget_rank_quartiles, COUNT_IF(location = 'New York') AS new_york_events FROM with_windows GROUP BY CASE WHEN budget_avg_2 >= 3864974 THEN 'LARGE' ELSE 'SMALL' END ORDER BY new_york_events;
